fn largest<T: PartialOrd + Copy>(list &[T]) T {
mut max := list[0]
for &item in list {if item > max {max = item}}
max
}
fn main() {
ints := [3, 7, 2, 9, 4]
floats := [1.5, 0.3, 2.7]
chars := ['m', 'z', 'a']
println!("{}", largest(&ints))
println!("{}", largest(&floats))
println!("{}", largest(&chars))
}

